"use client";

import { addClassNamesToElement } from "@lexical/utils";
import type {
  DOMConversionMap,
  DOMConversionOutput,
  DOMExportOutput,
  EditorConfig,
  LexicalNode,
  LexicalUpdateJSON,
  NodeKey,
  SerializedLexicalNode,
  Spread,
} from "lexical";
import { DecoratorNode } from "lexical";
import type { JSX } from "react";
import { ImageComponent } from "../../../plugins/image/component";

export type SerializedImageNode = Spread<
  {
    alignment?: ImageAlignment;
    altText: string;
    height: number | "inherit";
    src: string;
    width: number | "inherit";
  },
  SerializedLexicalNode
>;

export type ImageAlignment = "left" | "center" | "right";

export interface ImagePayload {
  alignment?: ImageAlignment;
  altText: string;
  height?: number | "inherit";
  key?: NodeKey;
  src: string;
  width?: number | "inherit";
}

const getImageAlignment = (domNode: HTMLImageElement): ImageAlignment => {
  const align = domNode.getAttribute("align");

  if (align === "center" || align === "right" || align === "left") {
    return align;
  }

  const { marginLeft, marginRight } = domNode.style;

  if (marginLeft === "auto" && marginRight === "auto") {
    return "center";
  }

  if (marginLeft === "auto") {
    return "right";
  }

  return "left";
};

const convertImageElement = (domNode: Node): DOMConversionOutput | null => {
  if (!(domNode instanceof HTMLImageElement)) {
    return null;
  }

  const src = domNode.getAttribute("src");
  if (!src || src.startsWith("file:///")) {
    return null;
  }

  return {
    node: $createImageNode({
      alignment: getImageAlignment(domNode),
      altText: domNode.getAttribute("alt") ?? "",
      height: domNode.height || undefined,
      src,
      width: domNode.width || undefined,
    }),
  };
};

export class ImageNode extends DecoratorNode<JSX.Element> {
  __alignment: ImageAlignment;
  __altText: string;
  __height: number | "inherit";
  __src: string;
  __width: number | "inherit";

  constructor(
    src: string,
    altText: string,
    alignment: ImageAlignment = "left",
    width: number | "inherit" = "inherit",
    height: number | "inherit" = "inherit",
    key?: NodeKey
  ) {
    super(key);
    this.__src = src;
    this.__altText = altText;
    this.__alignment = alignment;
    this.__width = width;
    this.__height = height;
  }

  static getType(): string {
    return "image";
  }

  static clone(node: ImageNode): ImageNode {
    return new ImageNode(
      node.__src,
      node.__altText,
      node.__alignment,
      node.__width,
      node.__height,
      node.__key
    );
  }

  static importDOM(): DOMConversionMap | null {
    return {
      img: () => ({
        conversion: convertImageElement,
        priority: 2,
      }),
    };
  }

  static importJSON(serializedNode: SerializedImageNode): ImageNode {
    return $createImageNode({
      alignment: serializedNode.alignment,
      altText: serializedNode.altText,
      height: serializedNode.height,
      src: serializedNode.src,
      width: serializedNode.width,
    }).updateFromJSON(serializedNode);
  }

  updateFromJSON(serializedNode: LexicalUpdateJSON<SerializedImageNode>): this {
    return super
      .updateFromJSON(serializedNode)
      .setAlignment(serializedNode.alignment ?? "left")
      .setAltText(serializedNode.altText)
      .setHeight(serializedNode.height)
      .setSrc(serializedNode.src)
      .setWidth(serializedNode.width);
  }

  exportDOM(): DOMExportOutput {
    const element = document.createElement("img");
    element.setAttribute("src", this.__src);
    element.setAttribute("alt", this.__altText);
    element.style.display = "block";

    if (this.__alignment === "center") {
      element.style.marginLeft = "auto";
      element.style.marginRight = "auto";
    } else if (this.__alignment === "right") {
      element.style.marginLeft = "auto";
      element.style.marginRight = "0";
    }

    if (this.__width !== "inherit") {
      element.width = this.__width;
    }

    if (this.__height !== "inherit") {
      element.height = this.__height;
    }

    return { element };
  }

  exportJSON(): SerializedImageNode {
    return {
      ...super.exportJSON(),
      alignment: this.__alignment,
      altText: this.__altText,
      height: this.__height,
      src: this.__src,
      type: "image",
      version: 1,
      width: this.__width,
    };
  }

  createDOM(config: EditorConfig): HTMLElement {
    const span = document.createElement("span");

    if (typeof config.theme.image === "string") {
      addClassNamesToElement(span, config.theme.image);
    }

    return span;
  }

  updateDOM(): false {
    return false;
  }

  decorate(): JSX.Element {
    return (
      <ImageComponent
        alignment={this.__alignment}
        altText={this.__altText}
        height={this.__height}
        nodeKey={this.getKey()}
        src={this.__src}
        width={this.__width}
      />
    );
  }

  isInline(): false {
    return false;
  }

  getSrc(): string {
    return this.getLatest().__src;
  }

  getAltText(): string {
    return this.getLatest().__altText;
  }

  getAlignment(): ImageAlignment {
    return this.getLatest().__alignment;
  }

  getWidth(): number | "inherit" {
    return this.getLatest().__width;
  }

  getHeight(): number | "inherit" {
    return this.getLatest().__height;
  }

  setAltText(altText: string): this {
    const writable = this.getWritable();
    writable.__altText = altText;
    return writable;
  }

  setAlignment(alignment: ImageAlignment): this {
    const writable = this.getWritable();
    writable.__alignment = alignment;
    return writable;
  }

  setWidth(width: number | "inherit"): this {
    const writable = this.getWritable();
    writable.__width = width;
    return writable;
  }

  setWidthAndHeight(
    width: number | "inherit",
    height: number | "inherit"
  ): this {
    const writable = this.getWritable();
    writable.__width = width;
    writable.__height = height;
    return writable;
  }

  setHeight(height: number | "inherit"): this {
    const writable = this.getWritable();
    writable.__height = height;
    return writable;
  }

  setSrc(src: string): this {
    const writable = this.getWritable();
    writable.__src = src;
    return writable;
  }
}

export function $createImageNode({
  alignment,
  altText,
  height,
  key,
  src,
  width,
}: ImagePayload): ImageNode {
  return new ImageNode(
    src,
    altText,
    alignment ?? "left",
    width ?? "inherit",
    height ?? "inherit",
    key
  );
}

export function $isImageNode(
  node: LexicalNode | null | undefined
): node is ImageNode {
  return node instanceof ImageNode;
}

import type { ElementTransformer } from "@lexical/markdown";
import { $createImageNode, $isImageNode, ImageNode } from "./node";

const IMAGE_REGEXP = /^!\[([^\]]*)\]\(([^)\s]+)\)$/;

export const IMAGE_MARKDOWN_TRANSFORMER: ElementTransformer = {
  dependencies: [ImageNode],
  export: (node) => {
    if (!$isImageNode(node)) {
      return null;
    }

    return `![${node.getAltText().replace(/]/g, "\\]")}](${node.getSrc()})`;
  },
  regExp: IMAGE_REGEXP,
  replace: (parentNode, _children, match) => {
    const [, altText, src] = match;
    parentNode.replace(
      $createImageNode({
        altText,
        src,
      })
    );
  },
  type: "element",
};

import type { NodeKey } from "lexical";
import { createCommand } from "lexical";
import type { ImageAlignment } from "../../core/nodes/image/node";

export interface InsertImagePayload {
  alignment?: ImageAlignment;
  altText?: string;
  /**
   * When omitted or empty the plugin opens its own insert dialog instead of
   * inserting directly — this is how the slash menu and toolbar trigger the
   * pick-a-source flow without owning any dialog UI themselves.
   */
  src?: string;
  targetNodeKey?: NodeKey;
}

export const INSERT_IMAGE_COMMAND = createCommand<InsertImagePayload>(
  "INSERT_IMAGE_COMMAND"
);

"use client";

import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { useLexicalEditable } from "@lexical/react/useLexicalEditable";
import { useLexicalNodeSelection } from "@lexical/react/useLexicalNodeSelection";
import { mergeRegister } from "@lexical/utils";
import {
  $getNodeByKey,
  $getSelection,
  $isNodeSelection,
  CLICK_COMMAND,
  COMMAND_PRIORITY_LOW,
  DRAGSTART_COMMAND,
  FORMAT_ELEMENT_COMMAND,
  KEY_BACKSPACE_COMMAND,
  KEY_DELETE_COMMAND,
  type NodeKey,
} from "lexical";
import { useEffect, useRef, useState } from "react";
import { $isImageNode, type ImageAlignment } from "../../core/nodes/image/node";
import { ImageResizer } from "./resizer";

interface ImageComponentProps {
  alignment: ImageAlignment;
  altText: string;
  height: number | "inherit";
  nodeKey: NodeKey;
  src: string;
  width: number | "inherit";
}

const DEFAULT_IMAGE_WIDTH = 640;

export function ImageComponent({
  alignment,
  altText,
  height,
  nodeKey,
  src,
  width,
}: ImageComponentProps) {
  const [editor] = useLexicalComposerContext();
  const editable = useLexicalEditable();
  const [isSelected, setSelected, clearSelection] =
    useLexicalNodeSelection(nodeKey);
  const imageRef = useRef<HTMLImageElement | null>(null);
  const [isResizing, setIsResizing] = useState(false);
  const effectiveWidth = width === "inherit" ? DEFAULT_IMAGE_WIDTH : width;
  const isInNodeSelection = (() => {
    if (!isSelected) {
      return false;
    }

    return editor.getEditorState().read(() => {
      const selection = $getSelection();
      return $isNodeSelection(selection) && selection.has(nodeKey);
    });
  })();
  const isFocused = (isSelected || isResizing) && editable;
  let figureClassName = "my-4 w-fit max-w-full";
  let alignmentClassName = "inline-flex max-w-full";

  if (alignment === "center") {
    figureClassName = "my-4 w-full";
    alignmentClassName = "flex max-w-full justify-center";
  } else if (alignment === "right") {
    figureClassName = "my-4 ml-auto w-fit max-w-full";
    alignmentClassName = "flex max-w-full justify-end";
  }

  useEffect(() => {
    if (!editable) {
      return;
    }

    const removeSelectedImage = (event: KeyboardEvent) => {
      const selection = $getSelection();
      if (!(isSelected && $isNodeSelection(selection))) {
        return false;
      }

      event.preventDefault();

      editor.update(() => {
        const node = $getNodeByKey(nodeKey);
        if ($isImageNode(node)) {
          node.remove();
        }
      });

      return true;
    };

    return mergeRegister(
      editor.registerCommand(
        CLICK_COMMAND,
        (event) => {
          if (isResizing) {
            return true;
          }

          if (event.target !== imageRef.current) {
            return false;
          }

          if (event.shiftKey) {
            setSelected(!isSelected);
          } else {
            clearSelection();
            setSelected(true);
          }

          return true;
        },
        COMMAND_PRIORITY_LOW
      ),
      editor.registerCommand(
        DRAGSTART_COMMAND,
        (event) => {
          if (event.target === imageRef.current) {
            event.preventDefault();
            return true;
          }

          return false;
        },
        COMMAND_PRIORITY_LOW
      ),
      editor.registerCommand(
        FORMAT_ELEMENT_COMMAND,
        (format) => {
          if (!isSelected) {
            return false;
          }

          if (
            !(format === "left" || format === "center" || format === "right")
          ) {
            return false;
          }

          editor.update(() => {
            const node = $getNodeByKey(nodeKey);
            if ($isImageNode(node)) {
              node.setAlignment(format as ImageAlignment);
            }
          });

          return true;
        },
        COMMAND_PRIORITY_LOW
      ),
      editor.registerCommand(
        KEY_BACKSPACE_COMMAND,
        removeSelectedImage,
        COMMAND_PRIORITY_LOW
      ),
      editor.registerCommand(
        KEY_DELETE_COMMAND,
        removeSelectedImage,
        COMMAND_PRIORITY_LOW
      )
    );
  }, [
    clearSelection,
    editable,
    editor,
    isResizing,
    isSelected,
    nodeKey,
    setSelected,
  ]);

  useEffect(() => {
    return () => {
      document.body.style.removeProperty("cursor");
      document.body.style.removeProperty("-webkit-user-select");
      document.body.style.removeProperty("user-select");
    };
  }, []);

  return (
    <figure className={figureClassName}>
      <div className={alignmentClassName}>
        <div className="relative inline-flex max-w-full">
          <div
            className={
              isFocused
                ? "rounded-2xl ring-1 ring-primary/40 ring-offset-2 ring-offset-background"
                : "rounded-2xl"
            }
          >
            <img
              alt={altText}
              className="block h-auto max-w-full rounded-xl border border-border/60 bg-muted/20 shadow-xs"
              draggable="false"
              height={height === "inherit" ? undefined : height}
              ref={imageRef}
              src={src}
              width={effectiveWidth}
            />
          </div>

          {editable && isInNodeSelection && isFocused ? (
            <ImageResizer
              editor={editor}
              imageRef={imageRef}
              onResizeEnd={(nextWidth, nextHeight) => {
                window.setTimeout(() => {
                  setIsResizing(false);
                }, 200);

                editor.update(() => {
                  const node = $getNodeByKey(nodeKey);
                  if ($isImageNode(node)) {
                    node.setWidthAndHeight(nextWidth, nextHeight);
                  }
                });
              }}
              onResizeStart={() => {
                setIsResizing(true);
              }}
            />
          ) : null}
        </div>
      </div>
    </figure>
  );
}

import { ImageIcon } from "lucide-react";
import { ImageNode } from "../../core/nodes/image/node";
import { IMAGE_MARKDOWN_TRANSFORMER } from "../../core/nodes/image/transformer";
import type { ExtraEditorFeature } from "../../core/types";
import { INSERT_IMAGE_COMMAND } from "./commands";
import { ImagePlugin } from "./plugin";

/**
 * Installs the image feature: the `ImageNode`, drag-drop/paste handling, the
 * markdown `![alt](src)` transformer and the shared insert-menu entry. Ships
 * as the `editor-image` registry item.
 */
export const imageFeature: ExtraEditorFeature = {
  id: "image",
  nodes: [ImageNode],
  plugin: ImagePlugin,
  slashCommands: [
    {
      command: {
        description: "Insert an image from URL",
        icon: ImageIcon,
        id: "image",
        keywords: ["image", "photo", "media", "picture", "img"],
        label: "Image",
      },
      run: (editor) => {
        editor.dispatchCommand(INSERT_IMAGE_COMMAND, {});
      },
    },
  ],
  transformers: [IMAGE_MARKDOWN_TRANSFORMER],
};

import type { ChangeEvent } from "react";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";

interface InsertImageDialogProps {
  /** Prefix for form input ids so multiple mounted dialogs stay unique. */
  idPrefix?: string;
  imageAltText: string;
  imageFileName: string;
  imageFileSrc: string | null;
  imageUrl: string;
  onAltTextChange: (value: string) => void;
  onCancel: () => void;
  onImageFileChange: (event: ChangeEvent<HTMLInputElement>) => void;
  onSubmit: () => void;
  onUrlChange: (value: string) => void;
  open: boolean;
}

export function InsertImageDialog({
  idPrefix = "slash",
  imageAltText,
  imageFileName,
  imageFileSrc,
  imageUrl,
  onAltTextChange,
  onCancel,
  onImageFileChange,
  onSubmit,
  onUrlChange,
  open,
}: InsertImageDialogProps) {
  const handleOpenChange = (nextOpen: boolean) => {
    if (!nextOpen) {
      onCancel();
    }
  };

  return (
    <Dialog onOpenChange={handleOpenChange} open={open}>
      <DialogContent className="sm:max-w-lg" showCloseButton>
        <DialogHeader>
          <DialogTitle>Insert image</DialogTitle>
          <DialogDescription>
            Add an external image URL and optional alt text.
          </DialogDescription>
        </DialogHeader>

        <form
          className="space-y-4"
          onSubmit={(event) => {
            event.preventDefault();
            onSubmit();
          }}
        >
          <div className="grid gap-2">
            <label
              className="font-medium text-sm"
              htmlFor={`${idPrefix}-image-url`}
            >
              Image URL
            </label>
            <Input
              id={`${idPrefix}-image-url`}
              onChange={(event) => onUrlChange(event.target.value)}
              placeholder="https://example.com/image.jpg"
              ref={(element) => {
                if (element && open) {
                  element.focus();
                }
              }}
              type="url"
              value={imageUrl}
            />
          </div>

          <div className="grid gap-2">
            <label
              className="font-medium text-sm"
              htmlFor={`${idPrefix}-image-file`}
            >
              Local file
            </label>
            <Input
              accept="image/*"
              id={`${idPrefix}-image-file`}
              onChange={onImageFileChange}
              type="file"
            />
            {imageFileName ? (
              <p className="text-muted-foreground text-xs">
                Selected: {imageFileName}
              </p>
            ) : null}
          </div>

          <div className="grid gap-2">
            <label
              className="font-medium text-sm"
              htmlFor={`${idPrefix}-image-alt`}
            >
              Alt text
            </label>
            <Textarea
              id={`${idPrefix}-image-alt`}
              onChange={(event) => onAltTextChange(event.target.value)}
              placeholder="Describe the image for accessibility"
              rows={3}
              value={imageAltText}
            />
          </div>

          <DialogFooter showCloseButton={false}>
            <Button onClick={onCancel} type="button" variant="outline">
              Cancel
            </Button>
            <Button disabled={!(imageFileSrc || imageUrl.trim())} type="submit">
              Insert image
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { DRAG_DROP_PASTE, eventFiles } from "@lexical/rich-text";
import {
  $createParagraphNode,
  $getNodeByKey,
  $getSelection,
  $insertNodes,
  $isElementNode,
  $isRangeSelection,
  $isTextNode,
  COMMAND_PRIORITY_EDITOR,
  COMMAND_PRIORITY_HIGH,
  DROP_COMMAND,
  PASTE_COMMAND,
} from "lexical";
import { useEffect, useState } from "react";
import { $createImageNode, $isImageNode } from "../../core/nodes/image/node";
import type { InsertImagePayload } from "./commands";
import { INSERT_IMAGE_COMMAND } from "./commands";
import { InsertImageDialog } from "./insert-dialog";
import { getFirstImageFile, readFileAsDataUrl } from "./utils";

const insertParagraphAfterImage = (
  imageNode: ReturnType<typeof $createImageNode>
) => {
  if (!$isImageNode(imageNode)) {
    return;
  }

  const paragraph = $createParagraphNode();
  imageNode.insertAfter(paragraph);
  paragraph.select();
};

const EMPTY_DIALOG_STATE = {
  altText: "",
  fileName: "",
  fileSrc: null as string | null,
  open: false,
  pendingTargetKey: null as string | null,
  url: "",
};

export function ImagePlugin() {
  const [editor] = useLexicalComposerContext();
  const [dialogState, setDialogState] = useState(EMPTY_DIALOG_STATE);

  useEffect(() => {
    const insertImage = ({
      alignment,
      altText,
      src,
      targetNodeKey,
    }: InsertImagePayload) => {
      const trimmedSrc = src?.trim();
      if (!trimmedSrc) {
        return false;
      }

      const imageNode = $createImageNode({
        alignment,
        altText: altText?.trim() ?? "",
        src: trimmedSrc,
      });

      if (targetNodeKey) {
        const targetNode = $getNodeByKey(targetNodeKey);
        if (!$isElementNode(targetNode)) {
          return false;
        }

        targetNode.replace(imageNode);
        insertParagraphAfterImage(imageNode);
        return true;
      }

      const selection = $getSelection();
      if (!$isRangeSelection(selection)) {
        return false;
      }

      $insertNodes([imageNode]);
      insertParagraphAfterImage(imageNode);
      return true;
    };

    return editor.registerCommand(
      INSERT_IMAGE_COMMAND,
      (payload) => insertImage(payload),
      COMMAND_PRIORITY_EDITOR
    );
  }, [editor]);

  // Incomplete payloads (no src) mean "open the pick-a-source dialog". The
  // slash menu and toolbars dispatch the bare command; the target block is
  // captured here so the dialog submit replaces it.
  useEffect(() => {
    return editor.registerCommand(
      INSERT_IMAGE_COMMAND,
      (payload) => {
        if (payload.src?.trim()) {
          return false;
        }

        let targetNodeKey: string | null = payload.targetNodeKey ?? null;

        if (!targetNodeKey) {
          editor.getEditorState().read(() => {
            const selection = $getSelection();
            if (!$isRangeSelection(selection)) {
              return;
            }
            const node = selection.anchor.getNode();
            if ($isTextNode(node)) {
              targetNodeKey = node.getTopLevelElementOrThrow().getKey();
            }
          });
        }

        setDialogState({
          ...EMPTY_DIALOG_STATE,
          open: true,
          pendingTargetKey: targetNodeKey,
        });
        return true;
      },
      COMMAND_PRIORITY_HIGH
    );
  }, [editor]);

  useEffect(() => {
    const insertImageFile = async (file: File) => {
      const src = await readFileAsDataUrl(file);

      editor.update(() => {
        editor.dispatchCommand(INSERT_IMAGE_COMMAND, {
          altText: file.name,
          src,
        });
      });
    };

    return editor.registerCommand(
      DRAG_DROP_PASTE,
      (files) => {
        const imageFile = getFirstImageFile(files);
        if (!imageFile) {
          return false;
        }

        insertImageFile(imageFile).catch(() => undefined);
        return true;
      },
      COMMAND_PRIORITY_HIGH
    );
  }, [editor]);

  useEffect(() => {
    return editor.registerCommand(
      PASTE_COMMAND,
      (event) => {
        const [, files] = eventFiles(event);
        const imageFile = getFirstImageFile(files);
        if (!imageFile) {
          return false;
        }

        event.preventDefault();
        editor.dispatchCommand(DRAG_DROP_PASTE, [imageFile]);
        return true;
      },
      COMMAND_PRIORITY_HIGH
    );
  }, [editor]);

  useEffect(() => {
    return editor.registerCommand(
      DROP_COMMAND,
      (event) => {
        const [, files] = eventFiles(event);
        const imageFile = getFirstImageFile(files);
        if (!imageFile) {
          return false;
        }

        event.preventDefault();
        editor.dispatchCommand(DRAG_DROP_PASTE, [imageFile]);
        return true;
      },
      COMMAND_PRIORITY_HIGH
    );
  }, [editor]);

  const closeDialog = () => {
    setDialogState(EMPTY_DIALOG_STATE);
  };

  const handleSubmit = () => {
    if (!(dialogState.fileSrc || dialogState.url.trim())) {
      return;
    }

    editor.update(() => {
      editor.dispatchCommand(INSERT_IMAGE_COMMAND, {
        altText: dialogState.altText,
        src: dialogState.fileSrc ?? dialogState.url.trim(),
        targetNodeKey: dialogState.pendingTargetKey ?? undefined,
      });
    });
    closeDialog();
  };

  return (
    <InsertImageDialog
      idPrefix="image-plugin"
      imageAltText={dialogState.altText}
      imageFileName={dialogState.fileName}
      imageFileSrc={dialogState.fileSrc}
      imageUrl={dialogState.url}
      onAltTextChange={(value) =>
        setDialogState((state) => ({ ...state, altText: value }))
      }
      onCancel={closeDialog}
      onImageFileChange={(event) => {
        const file = event.target.files?.[0];
        if (!file) {
          return;
        }
        readFileAsDataUrl(file)
          .then((src) => {
            setDialogState((state) => ({
              ...state,
              fileName: file.name,
              fileSrc: src,
            }));
          })
          .catch(() => {
            setDialogState((state) => ({ ...state, fileSrc: null }));
          });
      }}
      onSubmit={handleSubmit}
      onUrlChange={(value) =>
        setDialogState((state) => ({ ...state, url: value }))
      }
      open={dialogState.open}
    />
  );
}

export type CornerDirection = "ne" | "nw" | "se" | "sw";
export type EdgeDirection = "e" | "n" | "s" | "w";
export type ResizeDirection = CornerDirection | EdgeDirection;

export interface ResizeState {
  currentHeight: number;
  currentWidth: number;
  direction: ResizeDirection;
  isResizing: boolean;
  ratio: number;
  startHeight: number;
  startWidth: number;
  startX: number;
  startY: number;
}

const MIN_WIDTH = 100;
const MIN_HEIGHT = 40;

const clamp = (value: number, min: number, max: number) =>
  Math.min(Math.max(value, min), max);

const isEast = (d: ResizeDirection) => d === "ne" || d === "se" || d === "e";

export const getCursor = (d: ResizeDirection) => {
  if (d === "n" || d === "s") {
    return "ns-resize";
  }

  if (d === "e" || d === "w") {
    return "ew-resize";
  }

  return d === "nw" || d === "se" ? "nwse-resize" : "nesw-resize";
};

/**
 * Computes the next box for a drag position. Corner drags stay width-driven
 * with locked aspect ratio; edge drags move one axis independently.
 */
export const computeNextSize = (
  positioning: ResizeState,
  clientX: number,
  clientY: number,
  zoom: number,
  maxWidthContainer: number
): { height: number; width: number } => {
  const dx = clientX / zoom - positioning.startX;
  const dy = clientY / zoom - positioning.startY;
  const { direction } = positioning;

  if (direction === "n" || direction === "s") {
    const delta = direction === "n" ? -dy : dy;
    return {
      height: clamp(
        positioning.startHeight + delta,
        MIN_HEIGHT,
        Number.MAX_SAFE_INTEGER
      ),
      width: positioning.startWidth,
    };
  }

  if (direction === "e" || direction === "w") {
    const delta = isEast(direction) ? dx : -dx;
    return {
      height: positioning.startHeight,
      width: clamp(
        positioning.startWidth + delta,
        MIN_WIDTH,
        maxWidthContainer
      ),
    };
  }

  const delta = isEast(direction) ? dx : -dx;
  const width = clamp(
    positioning.startWidth + delta,
    MIN_WIDTH,
    maxWidthContainer
  );
  return {
    height: width / positioning.ratio,
    width,
  };
};

"use client";

import { calculateZoomLevel } from "@lexical/utils";
import type { LexicalEditor } from "lexical";
import { useLayoutEffect, useRef } from "react";
import {
  type CornerDirection,
  computeNextSize,
  type EdgeDirection,
  getCursor,
  type ResizeDirection,
  type ResizeState,
} from "./resize-geometry";

interface ImageResizerProps {
  /**
   * Absolutely-positioned chrome (action buttons and the like) rendered
   * inside the bounds-synced overlay. Because the overlay tracks the
   * resized element's true box, decorations stay glued to its corners and
   * edges even when ancestor containers clamp the element's layout width.
   */
  decorations?: React.ReactNode;
  /**
   * Also render edge handles that resize a single axis freely. Corners keep
   * the aspect-ratio-locked behavior; opt in for blocks like drawings where
   * width and height are independent.
   */
  edgeHandles?: boolean;
  editor: LexicalEditor;
  /** Element being resized; any element with box dimensions works. */
  imageRef: { current: HTMLElement | null };
  maxWidth?: number;
  onResizeEnd: (width: number, height: number) => void;
  onResizeStart: () => void;
}

const CORNER_DIRECTIONS: CornerDirection[] = ["ne", "se", "sw", "nw"];
const EDGE_DIRECTIONS: EdgeDirection[] = ["n", "e", "s", "w"];

const CORNER_CLASSES: Record<CornerDirection, string> = {
  ne: "right-0 top-0 translate-x-1/2 -translate-y-1/2 cursor-nesw-resize",
  se: "bottom-0 right-0 translate-x-1/2 translate-y-1/2 cursor-nwse-resize",
  sw: "bottom-0 left-0 -translate-x-1/2 translate-y-1/2 cursor-nesw-resize",
  nw: "left-0 top-0 -translate-x-1/2 -translate-y-1/2 cursor-nwse-resize",
};

const EDGE_CLASSES: Record<EdgeDirection, string> = {
  e: "right-0 top-1/2 -translate-y-1/2 translate-x-1/2",
  n: "left-1/2 top-0 -translate-x-1/2 -translate-y-1/2",
  s: "bottom-0 left-1/2 -translate-x-1/2 translate-y-1/2",
  w: "left-0 top-1/2 -translate-y-1/2 -translate-x-1/2",
};

/** Edge handles are bars perpendicular to the axis they resize. */
const EDGE_BAR_CLASSES: Record<EdgeDirection, string> = {
  e: "h-6 w-1 cursor-ew-resize",
  n: "h-1 w-6 cursor-ns-resize",
  s: "h-1 w-6 cursor-ns-resize",
  w: "h-6 w-1 cursor-ew-resize",
};

/**
 * Corner and edge handles rendered in an overlay that mirrors the resized
 * element's true box, so handles stay glued to it even when ancestor
 * containers clamp its layout width.
 */
export function ImageResizer({
  decorations,
  editor,
  imageRef,
  maxWidth,
  onResizeEnd,
  onResizeStart,
  edgeHandles = false,
}: ImageResizerProps) {
  const controlWrapperRef = useRef<HTMLDivElement | null>(null);
  const userSelect = useRef({ priority: "", value: "default" });
  const positioningRef = useRef<ResizeState>({
    currentHeight: 0,
    currentWidth: 0,
    direction: "se",
    isResizing: false,
    ratio: 0,
    startHeight: 0,
    startWidth: 0,
    startX: 0,
    startY: 0,
  });

  const editorRootElement = editor.getRootElement();
  let maxWidthContainer = 100;
  if (maxWidth) {
    maxWidthContainer = maxWidth;
  } else if (editorRootElement) {
    maxWidthContainer = editorRootElement.getBoundingClientRect().width - 20;
  }

  // The overlay must track the element being resized, not the surrounding
  // container. The container is `max-w-full` and gets clamped to the content
  // column, but the element keeps its explicit box and can overflow it — so
  // `inset-0` (relative to the container) would detach the handles from the
  // element's true corners. Anchor instead to the element's layout geometry
  // (offset* are unaffected by ancestor transforms/zoom) and re-sync whenever
  // the element or its positioning context changes.
  //
  // `imageRef` (the stable ref object) is the dependency, not `.current`:
  // reading ref values during render is invalid. Callers bind the ref to an
  // element that persists for this component's lifetime — the overlay mounts
  // together with selection — and the ResizeObserver keeps bounds in sync
  // after that.
  useLayoutEffect(() => {
    const image = imageRef.current;
    const controlWrapper = controlWrapperRef.current;
    if (!(image && controlWrapper)) {
      return;
    }

    const syncBounds = () => {
      controlWrapper.style.left = `${image.offsetLeft}px`;
      controlWrapper.style.top = `${image.offsetTop}px`;
      controlWrapper.style.width = `${image.offsetWidth}px`;
      controlWrapper.style.height = `${image.offsetHeight}px`;
    };

    syncBounds();

    if (typeof ResizeObserver === "undefined") {
      return;
    }

    const observer = new ResizeObserver(syncBounds);
    observer.observe(image);
    const offsetParent = image.offsetParent;
    if (offsetParent) {
      observer.observe(offsetParent);
    }
    return () => observer.disconnect();
  }, [imageRef]);

  const setStartCursor = (direction: ResizeDirection) => {
    const cursor = getCursor(direction);
    editorRootElement?.style.setProperty("cursor", cursor, "important");
    document.body.style.setProperty("cursor", cursor, "important");
    userSelect.current.value = document.body.style.getPropertyValue(
      "-webkit-user-select"
    );
    userSelect.current.priority = document.body.style.getPropertyPriority(
      "-webkit-user-select"
    );
    document.body.style.setProperty("-webkit-user-select", "none", "important");
  };

  const setEndCursor = () => {
    editorRootElement?.style.setProperty("cursor", "text");
    document.body.style.setProperty("cursor", "default");
    document.body.style.setProperty(
      "-webkit-user-select",
      userSelect.current.value,
      userSelect.current.priority
    );
  };

  const handlePointerMove = (event: PointerEvent) => {
    const image = imageRef.current;
    const positioning = positioningRef.current;

    if (!(image && positioning.isResizing)) {
      return;
    }

    const zoom = calculateZoomLevel(image);
    const nextSize = computeNextSize(
      positioning,
      event.clientX,
      event.clientY,
      zoom,
      maxWidthContainer
    );

    image.style.width = `${nextSize.width}px`;
    image.style.height = `${nextSize.height}px`;
    positioning.currentHeight = nextSize.height;
    positioning.currentWidth = nextSize.width;
  };

  const handlePointerUp = () => {
    const image = imageRef.current;
    const controlWrapper = controlWrapperRef.current;
    const positioning = positioningRef.current;

    document.removeEventListener("pointermove", handlePointerMove);
    document.removeEventListener("pointerup", handlePointerUp);
    setEndCursor();

    if (!(image && controlWrapper && positioning.isResizing)) {
      return;
    }

    const width = positioning.currentWidth;
    const height = positioning.currentHeight;

    positioning.startWidth = 0;
    positioning.startHeight = 0;
    positioning.ratio = 0;
    positioning.startX = 0;
    positioning.startY = 0;
    positioning.currentWidth = 0;
    positioning.currentHeight = 0;
    positioning.isResizing = false;

    controlWrapper.classList.remove("image-control-wrapper--resizing");
    onResizeEnd(width, height);
  };

  const handlePointerDown = (
    event: React.PointerEvent<HTMLDivElement>,
    direction: ResizeDirection
  ) => {
    if (!editor.isEditable()) {
      return;
    }

    const image = imageRef.current;
    const controlWrapper = controlWrapperRef.current;

    if (!(image && controlWrapper)) {
      return;
    }

    event.preventDefault();

    const { height, width } = image.getBoundingClientRect();
    const zoom = calculateZoomLevel(image);
    const positioning = positioningRef.current;

    positioning.startWidth = width;
    positioning.startHeight = height;
    positioning.ratio = width / height;
    positioning.currentWidth = width;
    positioning.currentHeight = height;
    positioning.startX = event.clientX / zoom;
    positioning.startY = event.clientY / zoom;
    positioning.isResizing = true;
    positioning.direction = direction;

    setStartCursor(direction);
    onResizeStart();

    controlWrapper.classList.add("image-control-wrapper--resizing");
    image.style.height = `${height}px`;
    image.style.width = `${width}px`;

    document.addEventListener("pointermove", handlePointerMove);
    document.addEventListener("pointerup", handlePointerUp);
  };

  return (
    <div
      className="absolute [&.image-control-wrapper--resizing]:touch-none"
      ref={controlWrapperRef}
    >
      {CORNER_DIRECTIONS.map((direction) => (
        <div
          className={`absolute size-2 rounded-full border border-background/20 bg-foreground shadow-sm ${CORNER_CLASSES[direction]}`}
          key={direction}
          onPointerDown={(event) => handlePointerDown(event, direction)}
        />
      ))}
      {edgeHandles
        ? EDGE_DIRECTIONS.map((direction) => (
            <div
              className={`absolute rounded-full border border-background/20 bg-foreground shadow-sm ${EDGE_CLASSES[direction]} ${EDGE_BAR_CLASSES[direction]}`}
              key={direction}
              onPointerDown={(event) => handlePointerDown(event, direction)}
            />
          ))
        : null}
      {decorations}
    </div>
  );
}

const IMAGE_MIME_PREFIX = "image/";

export const isImageFile = (file: File): boolean => {
  return file.type.startsWith(IMAGE_MIME_PREFIX);
};

export const getFirstImageFile = (files: Iterable<File>): File | null => {
  for (const file of files) {
    if (isImageFile(file)) {
      return file;
    }
  }

  return null;
};

export const readFileAsDataUrl = async (file: File): Promise<string> => {
  return await new Promise((resolve, reject) => {
    const reader = new FileReader();

    reader.addEventListener("load", () => {
      if (typeof reader.result === "string") {
        resolve(reader.result);
        return;
      }

      reject(new Error("Image file could not be read as a data URL."));
    });

    reader.addEventListener("error", () => {
      reject(reader.error ?? new Error("Failed to read image file."));
    });

    reader.readAsDataURL(file);
  });
};
